#!/usr/bin/env python3

import json
import subprocess
from flask import Flask, jsonify

app = Flask(__name__)

class ClickHouseAPI:
    def execute_query(self, query):
        """Execute ClickHouse query and return results"""
        try:
            result = subprocess.run(
                ['clickhouse', 'client', '--query', query, '--format', 'JSONCompactEachRow'],
                capture_output=True,
                text=True,
                check=True
            )

            if not result.stdout.strip():
                return []

            # Parse JSON lines
            lines = result.stdout.strip().split('\n')
            return [json.loads(line) for line in lines if line.strip()]
        except subprocess.CalledProcessError as e:
            print(f"ClickHouse query error: {e.stderr}")
            raise

clickhouse = ClickHouseAPI()

@app.route('/api/top-products', methods=['GET'])
def get_top_products():
    try:
        query = """
        SELECT
            product_id,
            countIf(event_type = 'view') as view_count,
            countIf(event_type = 'cart') as cart_count,
            countIf(event_type = 'purchase') as purchase_count,
            sumIf(toFloat64(JSONExtractRaw(properties, 'price')), event_type = 'purchase') as revenue
        FROM analytics.product_events
        GROUP BY product_id
        ORDER BY purchase_count DESC
        LIMIT 10
        """

        results = clickhouse.execute_query(query)

        # Convert to proper JSON structure
        products = []
        for row in results:
            products.append({
                "product_id": row[0],
                "view_count": row[1],
                "cart_count": row[2],
                "purchase_count": row[3],
                "revenue": row[4] if row[4] else 0.0
            })

        return jsonify(products)

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/funnel', methods=['GET'])
def get_conversion_funnel():
    try:
        query = """
        SELECT
            event_type as step,
            uniq(user_id) as unique_users,
            COUNT(*) as total_events
        FROM analytics.product_events
        GROUP BY event_type
        ORDER BY
            CASE event_type
                WHEN 'view' THEN 1
                WHEN 'cart' THEN 2
                WHEN 'purchase' THEN 3
                ELSE 4
            END
        """

        results = clickhouse.execute_query(query)

        # Convert to proper JSON structure
        funnel = []
        for row in results:
            funnel.append({
                "step": row[0],
                "unique_users": row[1],
                "total_events": row[2]
            })

        return jsonify(funnel)

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/hourly', methods=['GET'])
def get_hourly_activity():
    try:
        query = """
        SELECT
            toStartOfHour(event_ts) as hour,
            event_type,
            COUNT(*) as event_count
        FROM analytics.product_events
        GROUP BY hour, event_type
        ORDER BY hour, event_type
        """

        results = clickhouse.execute_query(query)

        # Convert to proper JSON structure
        hourly = []
        for row in results:
            hourly.append({
                "hour": row[0],
                "event_type": row[1],
                "event_count": row[2]
            })

        return jsonify(hourly)

    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "healthy", "service": "egress-api"}), 200

if __name__ == '__main__':
    print(f"Starting egress API service on port 3000")
    app.run(host='0.0.0.0', port=3000, debug=False)

